package com.food.essensplan

import app.cash.sqldelight.Query
import app.cash.sqldelight.TransacterImpl
import app.cash.sqldelight.db.QueryResult
import app.cash.sqldelight.db.SqlDriver
import kotlin.Any
import kotlin.Long
import kotlin.String

public class WochenplanQueries(
  driver: SqlDriver,
) : TransacterImpl(driver) {
  public fun <T : Any> selectPlan(mapper: (
    tag: String,
    eintrag_kategorie: String,
    id: Long,
    name: String,
    gericht_kategorie: String,
  ) -> T): Query<T> = Query(-696_721_301, arrayOf("wochenplan_eintrag", "gericht"), driver,
      "Wochenplan.sq", "selectPlan", """
  |SELECT wochenplan_eintrag.tag, wochenplan_eintrag.kategorie AS eintrag_kategorie, gericht.id, gericht.name, gericht.kategorie AS gericht_kategorie
  |FROM wochenplan_eintrag
  |JOIN gericht ON wochenplan_eintrag.gericht_id = gericht.id
  """.trimMargin()) { cursor ->
    mapper(
      cursor.getString(0)!!,
      cursor.getString(1)!!,
      cursor.getLong(2)!!,
      cursor.getString(3)!!,
      cursor.getString(4)!!
    )
  }

  public fun selectPlan(): Query<SelectPlan> = selectPlan { tag, eintrag_kategorie, id, name,
      gericht_kategorie ->
    SelectPlan(
      tag,
      eintrag_kategorie,
      id,
      name,
      gericht_kategorie
    )
  }

  /**
   * @return The number of rows updated.
   */
  public fun deleteAllenPlan(): QueryResult<Long> {
    val result = driver.execute(1_147_876_482, """DELETE FROM wochenplan_eintrag""", 0)
    notifyQueries(1_147_876_482) { emit ->
      emit("wochenplan_eintrag")
    }
    return result
  }

  /**
   * @return The number of rows updated.
   */
  public fun insertEintrag(
    tag: String,
    kategorie: String,
    gericht_id: Long,
  ): QueryResult<Long> {
    val result = driver.execute(-928_496_241, """
        |INSERT INTO wochenplan_eintrag(tag, kategorie, gericht_id)
        |VALUES (?, ?, ?)
        """.trimMargin(), 3) {
          bindString(0, tag)
          bindString(1, kategorie)
          bindLong(2, gericht_id)
        }
    notifyQueries(-928_496_241) { emit ->
      emit("wochenplan_eintrag")
    }
    return result
  }

  /**
   * @return The number of rows updated.
   */
  public fun updateEintrag(
    gericht_id: Long,
    tag: String,
    kategorie: String,
  ): QueryResult<Long> {
    val result = driver.execute(-1_912_939_137,
        """UPDATE wochenplan_eintrag SET gericht_id = ? WHERE tag = ? AND kategorie = ?""", 3) {
          bindLong(0, gericht_id)
          bindString(1, tag)
          bindString(2, kategorie)
        }
    notifyQueries(-1_912_939_137) { emit ->
      emit("wochenplan_eintrag")
    }
    return result
  }

  /**
   * @return The number of rows updated.
   */
  public fun deleteEintraegeFuerGericht(gericht_id: Long): QueryResult<Long> {
    val result = driver.execute(-272_003_739,
        """DELETE FROM wochenplan_eintrag WHERE gericht_id = ?""", 1) {
          bindLong(0, gericht_id)
        }
    notifyQueries(-272_003_739) { emit ->
      emit("wochenplan_eintrag")
    }
    return result
  }
}
