enum class Screen {
    GERICHTE, WOCHENPLAN, EinkaufsListe, VERWALTEN
}

private val tage = listOf(
    "Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag"
)

// Eine Zeile im Formular. Menge bleibt ein String, weil sie getippt wird (und erst beim Speichern in Double umgewandelt wird).
private data class ZutatEingabe(val name: String = "", val menge: String = "", val einheit: String = "g")

// Wandelt die Formularzeilen in echte Zutaten um; leere oder kaputte Zeilen fallen weg
private fun List<ZutatEingabe>.alsZutatModels(): List<ZutatModel> = mapNotNull { zeile ->
    val menge = zeile.menge.replace(',', '.').toDoubleOrNull()
    if (zeile.name.isBlank() || menge == null || menge <= 0.0 || zeile.einheit.isBlank()) {
        null
    } else {
        ZutatModel(zeile.name.trim(), menge, zeile.einheit.trim())
    }
}

private fun kategorieName(kategorie: Kategorie): String = when (kategorie) {
    Kategorie.FRUEHSTUECK -> "Frühstück"
    Kategorie.MITTAGESSEN -> "Mittagessen"
    Kategorie.ABENDESSEN -> "Abendessen"
}

private fun kategorieIcon(kategorie: Kategorie): ImageVector = when (kategorie) {
    Kategorie.FRUEHSTUECK -> Icons.Default.FreeBreakfast
    Kategorie.MITTAGESSEN -> Icons.Default.LunchDining
    Kategorie.ABENDESSEN -> Icons.Default.DinnerDining
}

// ---------------------------------------------------------------------------
// App: hält den gesamten State, die Screens bekommen nur Daten + Callbacks
// ---------------------------------------------------------------------------
@Composable
@Preview
fun App(
    database: EssensplanDatabase,
    onExport: () -> Unit = {},
    onImport: () -> Unit = {}
) {
    var aktuellerScreen by remember { mutableStateOf(Screen.GERICHTE) }
    var anzahlProKategorie by remember { mutableStateOf<Map<String, Int>>(emptyMap()) }
    var wochenplan by remember { mutableStateOf<List<WochenplanEintrag>>(emptyList()) }
    var einkaufsliste by remember { mutableStateOf<List<ZutatModel>>(emptyList()) }
    var gerichtListe by remember { mutableStateOf<List<GerichtModel>>(emptyList()) }
    // Wird erhöht, wenn sich Gerichte/Zutaten ändern, damit die Einkaufsliste neu berechnet wird
    var datenVersion by remember { mutableStateOf(0) }
    val abgehakt = remember { mutableStateMapOf<Pair<String, String>, Boolean>() }
    val scope = rememberCoroutineScope()
    val snackbarHostState = remember { SnackbarHostState() }

    val aktualisiereGerichte = {
        val zeilen = database.gerichtQueries.selectAlleGerichte().executeAsList()
        anzahlProKategorie = zeilen.groupingBy { it.kategorie }.eachCount()
        gerichtListe = zeilen.map { gericht -> toGerichtModel(gericht, emptyList()) }
    }

    // Beim Start Zähler UND gespeicherten Plan laden, damit die Einkaufsliste
    // auch ohne Umweg über den Wochenplan-Screen gefüllt ist.
    LaunchedEffect(Unit) {
        aktualisiereGerichte()
        wochenplan = ladePlanAusDb(database)
    }

    LaunchedEffect(wochenplan, datenVersion) {
        einkaufsliste = ladeEinkaufsliste(database, wochenplan)
    }

    val navigation = listOf(
        Triple(Screen.GERICHTE, "Neu", Icons.Default.Add),
        Triple(Screen.WOCHENPLAN, "Wochenplan", Icons.Default.DateRange),
        Triple(Screen.EinkaufsListe, "Einkauf", Icons.Default.ShoppingCart),
        Triple(Screen.VERWALTEN, "Verwalten", Icons.Default.Edit),
    )

    EssensplanTheme {
        Scaffold(
            containerColor = MaterialTheme.colorScheme.background,
            contentWindowInsets = WindowInsets(0, 0, 0, 0),
            snackbarHost = { SnackbarHost(snackbarHostState) },
            bottomBar = {
                NavigationBar(containerColor = Color.White) {
                    for ((screen, label, icon) in navigation) {
                        NavigationBarItem(
                            selected = aktuellerScreen == screen,
                            onClick = { aktuellerScreen = screen },
                            icon = { Icon(icon, contentDescription = label) },
                            label = { Text(label) },
                            colors = NavigationBarItemDefaults.colors(
                                selectedIconColor = Color.White,
                                selectedTextColor = Tannengruen,
                                indicatorColor = Tannengruen,
                                unselectedIconColor = Tannengruen.copy(alpha = 0.6f),
                                unselectedTextColor = Tannengruen.copy(alpha = 0.6f),
                            )
                        )
                    }
                }
            }
        ) { innerPadding ->
            Box(modifier = Modifier.padding(innerPadding).fillMaxSize()) {
                Crossfade(targetState = aktuellerScreen, label = "screen") { screen ->
                    when (screen) {
                        Screen.GERICHTE -> GerichteScreen(
                            anzahlProKategorie = anzahlProKategorie,
                            onSpeichern = { name, kategorie, zutaten ->
                                // Gericht + Zutaten in EINER Transaktion: entweder alles oder nichts
                                database.transaction {
                                    database.gerichtQueries.insertGericht(name, kategorie.name)
                                    val neueId = database.gerichtQueries.lastInsertRowId().executeAsOne()
                                    for (zutat in zutaten) {
                                        database.gerichtQueries.insertZutat(
                                            neueId, zutat.name, zutat.menge, zutat.einheit
                                        )
                                    }
                                }
                                aktualisiereGerichte()
                            },
                            onExport = onExport,
                            onImport = onImport
                        )

                        Screen.WOCHENPLAN -> WochenplanScreen(
                            wochenplan = wochenplan,
                            onWuerfeln = {
                                val alleGerichte = database.gerichtQueries.selectAlleGerichte().executeAsList()
                                    .map { gericht -> toGerichtModel(gericht, emptyList()) }
                                val neuerPlan = generiereWochenplan(alleGerichte = alleGerichte)
                                speicherePlanInDb(database, neuerPlan)
                                abgehakt.clear()
                                wochenplan = neuerPlan
                            },
                            onTauschen = { eintrag ->
                                val alleGerichte = database.gerichtQueries.selectAlleGerichte().executeAsList()
                                    .map { gericht -> toGerichtModel(gericht, emptyList()) }
                                val ersatz = waehleErsatzgericht(wochenplan, alleGerichte, eintrag)
                                if (ersatz != null) {
                                    database.wochenplanQueries.updateEintrag(
                                        ersatz.id, eintrag.tag, eintrag.kategorie.name
                                    )
                                    wochenplan = ladePlanAusDb(database)
                                }
                                ersatz != null
                            },
                            kandidatenFuer = { eintrag ->
                                // Alle Gerichte der Kategorie, die diese Woche noch nicht verplant sind
                                val belegteIds = wochenplan.map { it.gericht.id }.toSet()
                                database.gerichtQueries.selectAlleGerichte().executeAsList()
                                    .filter { it.kategorie == eintrag.kategorie.name }
                                    .map { gericht -> toGerichtModel(gericht, emptyList()) }
                                    .filter { it.id !in belegteIds }
                                    .sortedBy { it.name.lowercase() }
                            },
                            onErsetzen = { eintrag, neuesGericht ->
                                database.wochenplanQueries.updateEintrag(
                                    neuesGericht.id, eintrag.tag, eintrag.kategorie.name
                                )
                                wochenplan = ladePlanAusDb(database)
                            }
                        )

                        Screen.VERWALTEN -> VerwaltenScreen(
                            gerichte = gerichtListe,
                            ladeZutaten = { id ->
                                database.gerichtQueries.selectAlleZutatenFuerGericht(id).executeAsList()
                                    .map { zeile -> ZutatModel(zeile.name, zeile.menge, zeile.einheit) }
                            },
                            onSpeichern = { id, name, zutaten ->
                                database.transaction {
                                    database.gerichtQueries.updateGericht(name, id)
                                    database.gerichtQueries.deleteZutatenFuerGericht(id)
                                    for (zutat in zutaten) {
                                        database.gerichtQueries.insertZutat(id, zutat.name, zutat.menge, zutat.einheit)
                                    }
                                }
                                aktualisiereGerichte()
                                wochenplan = ladePlanAusDb(database)
                                datenVersion++
                            },
                            onLoeschen = { id ->
                                val betroffene = wochenplan.filter { it.gericht.id == id }
                                val geloeschterName = gerichtListe.firstOrNull { it.id == id }?.name ?: "Gericht"
                                val ersetzt = mutableListOf<String>()
                                val luecken = mutableListOf<String>()

                                // Reihenfolge wichtig: erst alles, was auf das Gericht zeigt, dann das Gericht selbst.
                                // Danach rücken für die entstandenen Plan-Lücken passende Ersatzgerichte nach.
                                database.transaction {
                                    database.gerichtQueries.deleteZutatenFuerGericht(id)
                                    database.wochenplanQueries.deleteEintraegeFuerGericht(id)
                                    database.gerichtQueries.deleteGericht(id)

                                    val alleGerichte = database.gerichtQueries.selectAlleGerichte().executeAsList()
                                        .map { gericht -> toGerichtModel(gericht, emptyList()) }
                                    var planOhneGeloeschtes = wochenplan.filter { it.gericht.id != id }
                                    for (eintrag in betroffene) {
                                        val ersatz = waehleErsatzgericht(planOhneGeloeschtes, alleGerichte, eintrag)
                                        if (ersatz != null) {
                                            database.wochenplanQueries.insertEintrag(
                                                eintrag.tag, eintrag.kategorie.name, ersatz.id
                                            )
                                            planOhneGeloeschtes = planOhneGeloeschtes +
                                                WochenplanEintrag(eintrag.tag, eintrag.kategorie, ersatz)
                                            ersetzt.add("${eintrag.tag}: ${ersatz.name}")
                                        } else {
                                            luecken.add("${eintrag.tag} (${kategorieName(eintrag.kategorie)})")
                                        }
                                    }
                                }
                                aktualisiereGerichte()
                                wochenplan = ladePlanAusDb(database)
                                datenVersion++

                                val meldung = when {
                                    betroffene.isEmpty() -> "„$geloeschterName“ gelöscht"
                                    luecken.isEmpty() ->
                                        "„$geloeschterName“ gelöscht, im Plan ersetzt: ${ersetzt.joinToString()}"
                                    else ->
                                        "„$geloeschterName“ gelöscht, kein Ersatz frei für ${luecken.joinToString()}"
                                }
                                scope.launch { snackbarHostState.showSnackbar(meldung) }
                            }
                        )

                        Screen.EinkaufsListe -> EinkaufsScreen(
                            einkaufsliste = einkaufsliste,
                            abgehakt = abgehakt
                        )
                    }
                }
            }
        }
    }
}

