// ---------------------------------------------------------------------------
// Screen 1: Gerichte
// ---------------------------------------------------------------------------
@Composable
private fun GerichteScreen(
    anzahlProKategorie: Map<String, Int>,
    onSpeichern: (String, Kategorie, List<ZutatModel>) -> Unit,
    onExport: () -> Unit,
    onImport: () -> Unit
) {
    var neuerName by remember { mutableStateOf("") }
    var neueKategorie by remember { mutableStateOf(Kategorie.FRUEHSTUECK) }
    val zutatenFormular = remember { mutableStateListOf(ZutatEingabe()) }
    var zeigeOhneZutatenHinweis by remember { mutableStateOf(false) }
    val gesamt = anzahlProKategorie.values.sum()

    // Speichert das Gericht und setzt das Formular zurück
    val speichern = {
        onSpeichern(neuerName.trim(), neueKategorie, zutatenFormular.alsZutatModels())
        neuerName = ""
        zutatenFormular.clear()
        zutatenFormular.add(ZutatEingabe())
    }

    if (zeigeOhneZutatenHinweis) {
        AlertDialog(
            onDismissRequest = { zeigeOhneZutatenHinweis = false },
            icon = { Icon(Icons.Default.ShoppingCart, contentDescription = null, tint = Kupferrot) },
            title = { Text("Ohne Zutaten speichern?") },
            text = {
                Text("Dieses Gericht hat keine (vollständigen) Zutaten und taucht deshalb nicht in der Einkaufsliste auf. Zeilen mit leerem Namen oder ungültiger Menge werden ignoriert.")
            },
            confirmButton = {
                Button(
                    onClick = {
                        speichern()
                        zeigeOhneZutatenHinweis = false
                    }
                ) { Text("Trotzdem speichern") }
            },
            dismissButton = {
                TextButton(onClick = { zeigeOhneZutatenHinweis = false }) { Text("Zutaten ergänzen") }
            }
        )
    }

    Column(modifier = Modifier.fillMaxSize()) {
        ScreenHeader("Meine Gerichte", "$gesamt Gerichte gespeichert", Icons.Default.Restaurant)

        Column(
            modifier = Modifier
                .weight(1f)
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Kleine Statistik pro Kategorie
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                for (kategorie in Kategorie.entries) {
                    StatKachel(
                        modifier = Modifier.weight(1f),
                        kategorie = kategorie,
                        anzahl = anzahlProKategorie[kategorie.name] ?: 0
                    )
                }
            }

            // Neues Gericht
            WeisseKarte {
                Text("Neues Gericht", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)

                OutlinedTextField(
                    value = neuerName,
                    onValueChange = { neuerName = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Name des Gerichts") },
                    singleLine = true,
                    shape = RoundedCornerShape(16.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = Tannengruen,
                        focusedLabelColor = Tannengruen,
                        cursorColor = Tannengruen
                    )
                )

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    for (kategorie in Kategorie.entries) {
                        KategorieAuswahl(
                            modifier = Modifier.weight(1f),
                            kategorie = kategorie,
                            ausgewaehlt = neueKategorie == kategorie,
                            onClick = { neueKategorie = kategorie }
                        )
                    }
                }

                ZutatenEditor(zutatenFormular)

                Button(
                    onClick = {
                        if (zutatenFormular.alsZutatModels().isEmpty()) {
                            zeigeOhneZutatenHinweis = true
                        } else {
                            speichern()
                        }
                    },
                    enabled = neuerName.isNotBlank(),
                    modifier = Modifier.fillMaxWidth().height(52.dp),
                    shape = RoundedCornerShape(16.dp)
                ) {
                    Icon(Icons.Default.Add, contentDescription = null)
                    Spacer(Modifier.width(8.dp))
                    Text("Gericht speichern")
                }
            }

            // Datensicherung
            WeisseKarte {
                Text("Datensicherung", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
                Text(
                    "Alles bleibt lokal auf deinem Gerät. Ein Import ersetzt alle aktuellen Daten.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.65f)
                )
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Button(
                        onClick = onExport,
                        modifier = Modifier.weight(1f).height(48.dp),
                        shape = RoundedCornerShape(16.dp)
                    ) {
                        Icon(Icons.Default.FileUpload, contentDescription = null)
                        Spacer(Modifier.width(8.dp))
                        Text("Export")
                    }
                    OutlinedButton(
                        onClick = onImport,
                        modifier = Modifier.weight(1f).height(48.dp),
                        shape = RoundedCornerShape(16.dp),
                        colors = ButtonDefaults.outlinedButtonColors(contentColor = Kupferrot),
                        border = BorderStroke(1.dp, Kupferrot)
                    ) {
                        Icon(Icons.Default.FileDownload, contentDescription = null)
                        Spacer(Modifier.width(8.dp))
                        Text("Import")
                    }
                }
            }
        }
    }
}

@Composable
private fun StatKachel(modifier: Modifier, kategorie: Kategorie, anzahl: Int) {
    val farbe = farbeFuerKategorie(kategorie)
    Card(
        modifier = modifier,
        shape = RoundedCornerShape(20.dp),
        colors = CardDefaults.cardColors(containerColor = farbe.copy(alpha = 0.16f))
    ) {
        Column(
            modifier = Modifier.fillMaxWidth().padding(vertical = 14.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Icon(kategorieIcon(kategorie), contentDescription = null, tint = farbe)
            Text(
                "$anzahl",
                style = MaterialTheme.typography.titleLarge,
                fontWeight = FontWeight.Bold,
                color = farbe
            )
            Text(
                kategorieName(kategorie),
                style = MaterialTheme.typography.labelSmall,
                maxLines = 1
            )
        }
    }
}

@Composable
private fun KategorieAuswahl(
    modifier: Modifier,
    kategorie: Kategorie,
    ausgewaehlt: Boolean,
    onClick: () -> Unit
) {
    val farbe = farbeFuerKategorie(kategorie)
    val hintergrund by animateColorAsState(
        if (ausgewaehlt) farbe else farbe.copy(alpha = 0.14f),
        label = "kategorie-hintergrund"
    )
    val inhalt by animateColorAsState(
        if (ausgewaehlt) Color.White else farbe,
        label = "kategorie-inhalt"
    )
    Surface(
        onClick = onClick,
        modifier = modifier,
        shape = RoundedCornerShape(16.dp),
        color = hintergrund
    ) {
        Column(
            modifier = Modifier.padding(vertical = 14.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Icon(kategorieIcon(kategorie), contentDescription = null, tint = inhalt)
            Spacer(Modifier.height(4.dp))
            Text(
                kategorieName(kategorie),
                style = MaterialTheme.typography.labelMedium,
                fontWeight = FontWeight.SemiBold,
                color = inhalt,
                maxLines = 1
            )
        }
    }
}

// ---------------------------------------------------------------------------
// Zutaten-Editor (wird beim Anlegen UND beim Bearbeiten verwendet)
// ---------------------------------------------------------------------------
@Composable
private fun ZutatenEditor(zutatenFormular: SnapshotStateList<ZutatEingabe>) {
    Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
        Text("Zutaten", style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.SemiBold)

        zutatenFormular.forEachIndexed { index, zeile ->
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                color = Tannengruen.copy(alpha = 0.06f)
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    // Zeile 1: Name der Zutat + Entfernen
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        OutlinedTextField(
                            value = zeile.name,
                            onValueChange = { zutatenFormular[index] = zeile.copy(name = it) },
                            modifier = Modifier.weight(1f),
                            label = { Text("Zutat") },
                            singleLine = true,
                            shape = RoundedCornerShape(12.dp)
                        )
                        IconButton(
                            onClick = {
                                zutatenFormular.removeAt(index)
                                if (zutatenFormular.isEmpty()) zutatenFormular.add(ZutatEingabe())
                            }
                        ) {
                            Icon(Icons.Default.Close, contentDescription = "Zutat entfernen", tint = Kupferrot)
                        }
                    }
                    // Zeile 2: Menge und Einheit nebeneinander, beide gleich breit
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        OutlinedTextField(
                            value = zeile.menge,
                            onValueChange = { zutatenFormular[index] = zeile.copy(menge = it) },
                            modifier = Modifier.weight(1f),
                            label = { Text("Menge") },
                            singleLine = true,
                            isError = zeile.menge.isNotBlank() && zeile.menge.replace(',', '.').toDoubleOrNull() == null,
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                            shape = RoundedCornerShape(12.dp)
                        )
                        OutlinedTextField(
                            value = zeile.einheit,
                            onValueChange = { zutatenFormular[index] = zeile.copy(einheit = it) },
                            modifier = Modifier.weight(1f),
                            label = { Text("Einheit") },
                            singleLine = true,
                            shape = RoundedCornerShape(12.dp)
                        )
                    }
                }
            }
        }

        TextButton(onClick = { zutatenFormular.add(ZutatEingabe()) }) {
            Icon(Icons.Default.Add, contentDescription = null)
            Spacer(Modifier.width(8.dp))
            Text("Weitere Zutat")
        }
        Text(
            "Einheiten z. B.: g, ml, Stück, EL, TL, Schuss, Portion",
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.65f)
        )
    }
}

// ---------------------------------------------------------------------------
// Screen 4: Gerichte verwalten
// ---------------------------------------------------------------------------
@Composable
private fun VerwaltenScreen(
    gerichte: List<GerichtModel>,
    ladeZutaten: (Long) -> List<ZutatModel>,
    onSpeichern: (Long, String, List<ZutatModel>) -> Unit,
    onLoeschen: (Long) -> Unit
) {
    var suche by remember { mutableStateOf("") }
    var filter by remember { mutableStateOf<Kategorie?>(null) }
    var bearbeitet by remember { mutableStateOf<GerichtModel?>(null) }
    var zuLoeschen by remember { mutableStateOf<GerichtModel?>(null) }

    val sichtbar = gerichte
        .filter { filter == null || it.kategorie == filter }
        .filter { it.name.contains(suche.trim(), ignoreCase = true) }
        .sortedBy { it.name.lowercase() }

    Column(modifier = Modifier.fillMaxSize()) {
        ScreenHeader("Gerichte verwalten", "${gerichte.size} Gerichte gespeichert", Icons.Default.Edit)

        Column(
            modifier = Modifier.padding(start = 16.dp, end = 16.dp, top = 16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            OutlinedTextField(
                value = suche,
                onValueChange = { suche = it },
                modifier = Modifier.fillMaxWidth(),
                placeholder = { Text("Gericht suchen") },
                leadingIcon = { Icon(Icons.Default.Search, contentDescription = null) },
                trailingIcon = {
                    if (suche.isNotEmpty()) {
                        IconButton(onClick = { suche = "" }) {
                            Icon(Icons.Default.Close, contentDescription = "Suche löschen")
                        }
                    }
                },
                singleLine = true,
                shape = RoundedCornerShape(16.dp),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = Tannengruen,
                    cursorColor = Tannengruen,
                    unfocusedContainerColor = Color.White,
                    focusedContainerColor = Color.White
                )
            )
            Row(
                modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                FilterChip(
                    selected = filter == null,
                    onClick = { filter = null },
                    label = { Text("Alle") },
                    colors = FilterChipDefaults.filterChipColors(
                        selectedContainerColor = Tannengruen,
                        selectedLabelColor = Color.White
                    )
                )
                for (kategorie in Kategorie.entries) {
                    val farbe = farbeFuerKategorie(kategorie)
                    FilterChip(
                        selected = filter == kategorie,
                        onClick = { filter = if (filter == kategorie) null else kategorie },
                        label = { Text(kategorieName(kategorie)) },
                        leadingIcon = { Icon(kategorieIcon(kategorie), contentDescription = null, modifier = Modifier.size(18.dp)) },
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = farbe,
                            selectedLabelColor = Color.White,
                            selectedLeadingIconColor = Color.White,
                            iconColor = farbe
                        )
                    )
                }
            }
        }

        LazyColumn(
            modifier = Modifier.weight(1f),
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            if (sichtbar.isEmpty()) {
                item {
                    LeerZustand(
                        icon = Icons.Default.Search,
                        titel = "Nichts gefunden",
                        text = "Passe die Suche oder den Filter an."
                    )
                }
            }
            items(sichtbar, key = { it.id }) { gericht ->
                GerichtZeile(
                    gericht = gericht,
                    onBearbeiten = { bearbeitet = gericht },
                    onLoeschen = { zuLoeschen = gericht }
                )
            }
        }
    }

    bearbeitet?.let { gericht ->
        val startZutaten = remember(gericht.id) { ladeZutaten(gericht.id) }
        GerichtBearbeitenDialog(
            gericht = gericht,
            startZutaten = startZutaten,
            onSpeichern = { name, zutaten ->
                onSpeichern(gericht.id, name, zutaten)
                bearbeitet = null
            },
            onDismiss = { bearbeitet = null }
        )
    }

    zuLoeschen?.let { gericht ->
        AlertDialog(
            onDismissRequest = { zuLoeschen = null },
            icon = { Icon(Icons.Default.Delete, contentDescription = null, tint = Kupferrot) },
            title = { Text("Gericht löschen?") },
            text = {
                Text("„${gericht.name}“ wird samt Zutaten gelöscht. Steht es im aktuellen Wochenplan, wird es automatisch durch ein anderes freies Gericht derselben Kategorie ersetzt.")
            },
            confirmButton = {
                Button(
                    onClick = {
                        onLoeschen(gericht.id)
                        zuLoeschen = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Kupferrot)
                ) { Text("Löschen") }
            },
            dismissButton = { TextButton(onClick = { zuLoeschen = null }) { Text("Abbrechen") } }
        )
    }
}

@Composable
private fun GerichtZeile(
    gericht: GerichtModel,
    onBearbeiten: () -> Unit,
    onLoeschen: () -> Unit
) {
    val farbe = farbeFuerKategorie(gericht.kategorie)
    Card(
        modifier = Modifier.fillMaxWidth().clip(RoundedCornerShape(20.dp)).clickable { onBearbeiten() },
        shape = RoundedCornerShape(20.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth().padding(start = 14.dp, top = 8.dp, bottom = 8.dp, end = 4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier.size(40.dp).clip(CircleShape).background(farbe.copy(alpha = 0.16f)),
                contentAlignment = Alignment.Center
            ) {
                Icon(kategorieIcon(gericht.kategorie), contentDescription = null, tint = farbe)
            }
            Spacer(Modifier.width(12.dp))
            Column(modifier = Modifier.weight(1f)) {
                Text(gericht.name, style = MaterialTheme.typography.bodyLarge, fontWeight = FontWeight.Medium)
                Text(
                    kategorieName(gericht.kategorie),
                    style = MaterialTheme.typography.labelSmall,
                    color = farbe,
                    fontWeight = FontWeight.SemiBold
                )
            }
            IconButton(onClick = onBearbeiten) {
                Icon(Icons.Default.Edit, contentDescription = "Bearbeiten", tint = Tannengruen)
            }
            IconButton(onClick = onLoeschen) {
                Icon(Icons.Default.Delete, contentDescription = "Löschen", tint = Kupferrot)
            }
        }
    }
}

@Composable
private fun GerichtBearbeitenDialog(
    gericht: GerichtModel,
    startZutaten: List<ZutatModel>,
    onSpeichern: (String, List<ZutatModel>) -> Unit,
    onDismiss: () -> Unit
) {
    var name by remember(gericht.id) { mutableStateOf(gericht.name) }
    val zutaten = remember(gericht.id) {
        mutableStateListOf<ZutatEingabe>().apply {
            addAll(startZutaten.map { ZutatEingabe(it.name, formatMenge(it.menge), it.einheit) })
            if (isEmpty()) add(ZutatEingabe())
        }
    }
    val farbe = farbeFuerKategorie(gericht.kategorie)

    AlertDialog(
        onDismissRequest = onDismiss,
        icon = { Icon(kategorieIcon(gericht.kategorie), contentDescription = null, tint = farbe) },
        title = { Text("Gericht bearbeiten") },
        text = {
            Column(
                modifier = Modifier.heightIn(max = 460.dp).verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(14.dp)
            ) {
                OutlinedTextField(
                    value = name,
                    onValueChange = { name = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Name des Gerichts") },
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp)
                )
                Text(
                    "Kategorie: ${kategorieName(gericht.kategorie)}",
                    style = MaterialTheme.typography.labelMedium,
                    color = farbe,
                    fontWeight = FontWeight.SemiBold
                )
                ZutatenEditor(zutaten)
            }
        },
        confirmButton = {
            Button(
                onClick = { onSpeichern(name.trim(), zutaten.alsZutatModels()) },
                enabled = name.isNotBlank()
            ) { Text("Speichern") }
        },
        dismissButton = { TextButton(onClick = onDismiss) { Text("Abbrechen") } }
    )
}

// ---------------------------------------------------------------------------
// Screen 2: Wochenplan
// ---------------------------------------------------------------------------
@Composable
private fun WochenplanScreen(
    wochenplan: List<WochenplanEintrag>,
    onWuerfeln: () -> Unit,
    onTauschen: (WochenplanEintrag) -> Boolean,
    kandidatenFuer: (WochenplanEintrag) -> List<GerichtModel>,
    onErsetzen: (WochenplanEintrag, GerichtModel) -> Unit
) {
    var zeigeBestaetigung by remember { mutableStateOf(false) }
    var auswahlFuer by remember { mutableStateOf<WochenplanEintrag?>(null) }
    var keinErsatz by remember { mutableStateOf(false) }
    val nachTagGruppiert = wochenplan.groupBy { it.tag }

    Column(modifier = Modifier.fillMaxSize()) {
        ScreenHeader("Wochenplan", "Dein Menü für die Woche", Icons.Default.DateRange)

        Column(
            modifier = Modifier
                .weight(1f)
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Button(
                onClick = { if (wochenplan.isEmpty()) onWuerfeln() else zeigeBestaetigung = true },
                modifier = Modifier.fillMaxWidth().height(52.dp),
                shape = RoundedCornerShape(16.dp),
                colors = ButtonDefaults.buttonColors(containerColor = Kupferrot)
            ) {
                Icon(Icons.Default.Casino, contentDescription = null)
                Spacer(Modifier.width(8.dp))
                Text("Woche neu würfeln", fontWeight = FontWeight.SemiBold)
            }

            if (wochenplan.isEmpty()) {
                LeerZustand(
                    icon = Icons.Default.Casino,
                    titel = "Noch kein Plan",
                    text = "Würfle deine erste Woche – kein Gericht kommt doppelt vor."
                )
            } else {
                for (tag in tage) {
                    val eintraege = (nachTagGruppiert[tag] ?: emptyList()).sortedBy { it.kategorie }
                    if (eintraege.isNotEmpty()) {
                        TagesKarte(
                            tag = tag,
                            eintraege = eintraege,
                            onWuerfeln = { eintrag -> keinErsatz = !onTauschen(eintrag) },
                            onAuswaehlen = { eintrag -> auswahlFuer = eintrag }
                        )
                    }
                }
            }
        }
    }

    if (keinErsatz) {
        AlertDialog(
            onDismissRequest = { keinErsatz = false },
            title = { Text("Kein Ersatz frei") },
            text = { Text("Alle anderen Gerichte dieser Kategorie sind schon in dieser Woche verplant. Lege neue Gerichte an, dann klappt der Tausch.") },
            confirmButton = { TextButton(onClick = { keinErsatz = false }) { Text("OK") } }
        )
    }

    auswahlFuer?.let { eintrag ->
        val kandidaten = kandidatenFuer(eintrag)
        AlertDialog(
            onDismissRequest = { auswahlFuer = null },
            icon = {
                Icon(kategorieIcon(eintrag.kategorie), contentDescription = null, tint = farbeFuerKategorie(eintrag.kategorie))
            },
            title = { Text("${kategorieName(eintrag.kategorie)} am ${eintrag.tag}") },
            text = {
                if (kandidaten.isEmpty()) {
                    Text("Kein anderes Gericht dieser Kategorie ist frei. Alle sind schon in dieser Woche verplant.")
                } else {
                    Column(
                        modifier = Modifier.heightIn(max = 360.dp).verticalScroll(rememberScrollState())
                    ) {
                        Text(
                            "Aktuell: ${eintrag.gericht.name}",
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                        )
                        Spacer(Modifier.height(8.dp))
                        for (gericht in kandidaten) {
                            Text(
                                gericht.name,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(12.dp))
                                    .clickable {
                                        onErsetzen(eintrag, gericht)
                                        auswahlFuer = null
                                    }
                                    .padding(horizontal = 12.dp, vertical = 14.dp),
                                style = MaterialTheme.typography.bodyLarge
                            )
                            HorizontalDivider(color = Tannengruen.copy(alpha = 0.08f))
                        }
                    }
                }
            },
            confirmButton = {},
            dismissButton = { TextButton(onClick = { auswahlFuer = null }) { Text("Abbrechen") } }
        )
    }

    if (zeigeBestaetigung) {
        AlertDialog(
            onDismissRequest = { zeigeBestaetigung = false },
            icon = { Icon(Icons.Default.Casino, contentDescription = null, tint = Kupferrot) },
            title = { Text("Plan überschreiben?") },
            text = { Text("Der aktuelle Wochenplan wird gelöscht und durch einen neuen ersetzt.") },
            confirmButton = {
                Button(
                    onClick = {
                        onWuerfeln()
                        zeigeBestaetigung = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Kupferrot)
                ) {
                    Text("Ja, neu würfeln")
                }
            },
            dismissButton = {
                TextButton(onClick = { zeigeBestaetigung = false }) {
                    Text("Abbrechen")
                }
            }
        )
    }
}

@Composable
private fun TagesKarte(
    tag: String,
    eintraege: List<WochenplanEintrag>,
    onWuerfeln: (WochenplanEintrag) -> Unit,
    onAuswaehlen: (WochenplanEintrag) -> Unit
) {
    WeisseKarte {
        Text(
            tag,
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.Bold,
            color = Tannengruen
        )
        for (eintrag in eintraege) {
            val farbe = farbeFuerKategorie(eintrag.kategorie)
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(16.dp))
                    .clickable { onAuswaehlen(eintrag) },
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .clip(CircleShape)
                        .background(farbe.copy(alpha = 0.16f)),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(kategorieIcon(eintrag.kategorie), contentDescription = null, tint = farbe)
                }
                Spacer(Modifier.width(12.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        kategorieName(eintrag.kategorie),
                        style = MaterialTheme.typography.labelSmall,
                        color = farbe,
                        fontWeight = FontWeight.SemiBold
                    )
                    Text(eintrag.gericht.name, style = MaterialTheme.typography.bodyLarge)
                }
                IconButton(onClick = { onWuerfeln(eintrag) }) {
                    Icon(Icons.Default.Refresh, contentDescription = "Zufällig tauschen", tint = Tannengruen)
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Screen 3: Einkaufsliste
// ---------------------------------------------------------------------------
@Composable
private fun EinkaufsScreen(
    einkaufsliste: List<ZutatModel>,
    abgehakt: SnapshotStateMap<Pair<String, String>, Boolean>
) {
    val clipboard = LocalClipboard.current
    val scope = rememberCoroutineScope()
    val sortiert = einkaufsliste.sortedBy { it.name.lowercase() }
    val erledigt = sortiert.count { abgehakt[Pair(it.name, it.einheit)] == true }
    val anteil by animateFloatAsState(
        if (sortiert.isEmpty()) 0f else erledigt.toFloat() / sortiert.size,
        label = "fortschritt"
    )

    Column(modifier = Modifier.fillMaxSize()) {
        ScreenHeader("Einkaufsliste", "$erledigt von ${sortiert.size} erledigt", Icons.Default.ShoppingCart)

        Column(
            modifier = Modifier
                .weight(1f)
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            if (sortiert.isEmpty()) {
                LeerZustand(
                    icon = Icons.Default.ShoppingCart,
                    titel = "Die Liste ist leer",
                    text = "Sobald du einen Wochenplan würfelst, erscheinen hier alle Zutaten."
                )
            } else {
                // Fortschrittsbalken
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(10.dp)
                        .clip(CircleShape)
                        .background(Tannengruen.copy(alpha = 0.15f))
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(anteil)
                            .fillMaxHeight()
                            .clip(CircleShape)
                            .background(Tannengruen)
                    )
                }

                OutlinedButton(
                    onClick = {
                        val offene = sortiert.filter { abgehakt[Pair(it.name, it.einheit)] != true }
                        val text = offene.joinToString("\n") {
                            "${it.name}: ${formatMenge(it.menge)} ${it.einheit}"
                        }
                        scope.launch { kopiereInZwischenablage(clipboard, text) }
                    },
                    modifier = Modifier.fillMaxWidth().height(48.dp),
                    shape = RoundedCornerShape(16.dp),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Tannengruen),
                    border = BorderStroke(1.dp, Tannengruen)
                ) {
                    Icon(Icons.Default.ContentCopy, contentDescription = null)
                    Spacer(Modifier.width(8.dp))
                    Text("Offene Zutaten kopieren")
                }

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    elevation = CardDefaults.cardElevation(defaultElevation = 3.dp)
                ) {
                    Column(modifier = Modifier.padding(vertical = 8.dp)) {
                        sortiert.forEachIndexed { index, zutat ->
                            val schluessel = Pair(zutat.name, zutat.einheit)
                            val erledigtZutat = abgehakt[schluessel] == true
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { abgehakt[schluessel] = !erledigtZutat }
                                    .padding(horizontal = 12.dp, vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Checkbox(
                                    checked = erledigtZutat,
                                    onCheckedChange = null,
                                    colors = CheckboxDefaults.colors(checkedColor = Tannengruen),
                                    modifier = Modifier.padding(12.dp)
                                )
                                Text(
                                    zutat.name,
                                    modifier = Modifier.weight(1f),
                                    style = MaterialTheme.typography.bodyLarge,
                                    textDecoration = if (erledigtZutat) TextDecoration.LineThrough else null,
                                    color = if (erledigtZutat) {
                                        MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                                    } else {
                                        MaterialTheme.colorScheme.onSurface
                                    }
                                )
                                Text(
                                    "${formatMenge(zutat.menge)} ${zutat.einheit}",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.SemiBold,
                                    color = Kupferrot.copy(alpha = if (erledigtZutat) 0.4f else 1f)
                                )
                                Spacer(Modifier.width(8.dp))
                            }
                            if (index < sortiert.lastIndex) {
                                HorizontalDivider(
                                    modifier = Modifier.padding(horizontal = 16.dp),
                                    color = Tannengruen.copy(alpha = 0.08f)
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}