package com.food.essensplan

import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.graphics.Color

val Tannengruen = Color(0xFF2F4B3C)
val Kupferrot = Color(0xFFC1653B)
val SalbeiHell = Color(0xFFEAF0E6)
val Senfgelb = Color(0xFFD9A441)

private val EssensplanColors = lightColorScheme(
    primary = Tannengruen,
    onPrimary = Color.White,
    secondary = Kupferrot,
    onSecondary = Color.White,
    background = SalbeiHell,
    surface = Color.White,
    tertiary = Senfgelb
)

@Composable
fun EssensplanTheme(content: @Composable () -> Unit) {
    MaterialTheme(
        colorScheme = EssensplanColors,
        content = content
    )
}

fun farbeFuerKategorie(kategorie: Kategorie): Color = when (kategorie) {
    Kategorie.FRUEHSTUECK -> Senfgelb
    Kategorie.MITTAGESSEN -> Tannengruen
    Kategorie.ABENDESSEN -> Kupferrot
}