package com.food.essensplan

import com.food.essensplan.db.EssensplanDatabase
import kotlin.Double
import kotlin.String
import kotlin.math.round

enum class Kategorie {
    FRUEHSTUECK, MITTAGESSEN, ABENDESSEN
}

data class ZutatModel(val name: String, val menge: Double, val einheit: String)

data class GerichtModel(
    val id: Long,
    val name: String,
    val kategorie: Kategorie,
    val zutaten: List<ZutatModel>
)

data class WochenplanEintrag(
    val tag: String,
    val kategorie: Kategorie,
    val gericht: GerichtModel
)

fun toGerichtModel(gericht: com.food.essensplan.Gericht, zutaten: List<com.food.essensplan.Zutat>): GerichtModel {
    return GerichtModel(
        id = gericht.id,
        name = gericht.name,
        kategorie = Kategorie.valueOf(gericht.kategorie),
        zutaten = zutaten.map { zutat ->
            ZutatModel(name = zutat.name, menge = zutat.menge, einheit = zutat.einheit)
        }
    )
}

fun waehleSiebenGerichte(alleGerichte: List<GerichtModel>, kategorie: Kategorie): List<GerichtModel> {
    val passendeGerichte = alleGerichte.filter { it.kategorie == kategorie }

    return passendeGerichte.shuffled().take(7)
}

fun generiereWochenplan(alleGerichte: List<GerichtModel>): List<WochenplanEintrag> {
    val tage = listOf("Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag")
    val ergebnis = mutableListOf<WochenplanEintrag>()

    for (kategorie in Kategorie.entries) {
        val gewuerfelt = waehleSiebenGerichte(alleGerichte, kategorie)
        val tagGerichtPaare = tage.zip(gewuerfelt)

        for (paar in tagGerichtPaare) {
            ergebnis.add(
                WochenplanEintrag(
                    tag = paar.first,
                    gericht = paar.second,
                    kategorie = kategorie
                )
            )
        }
    }

    return ergebnis
}

fun speicherePlanInDb(database: EssensplanDatabase, plan: List<WochenplanEintrag>) {
    database.wochenplanQueries.deleteAllenPlan()

    for (eintrag in plan) {
        database.wochenplanQueries.insertEintrag(
            eintrag.tag,
            eintrag.kategorie.name,
            eintrag.gericht.id
        )
    }
}

fun ladePlanAusDb(database: EssensplanDatabase): List<WochenplanEintrag> {
    val zeilen = database.wochenplanQueries.selectPlan().executeAsList()

    return zeilen.map { zeile ->
        WochenplanEintrag(
            tag = zeile.tag,
            kategorie = Kategorie.valueOf(zeile.eintrag_kategorie),
            gericht = GerichtModel(
                id = zeile.id,
                name = zeile.name,
                kategorie = Kategorie.valueOf(zeile.gericht_kategorie),
                zutaten = emptyList()
            )
        )
    }
}

// Namen, die auf der Einkaufsliste als dieselbe Zutat gelten sollen (Schlüssel: kleingeschrieben)
private val zutatenAliase = mapOf(
    "magerquark" to "Quark",
    "speisequark" to "Quark",
)

// Vereinheitlicht Schreibweisen der Einheit
private fun normalisiereEinheit(einheit: String): String = when (einheit.trim().lowercase()) {
    "gr", "gramm" -> "g"
    "milliliter" -> "ml"
    "liter" -> "l"
    "stk", "stk.", "st.", "stück" -> "Stück"
    else -> einheit.trim()
}

// kg -> g und l -> ml, damit sich Mengen addieren lassen
private fun zuBasiseinheit(zutat: ZutatModel): ZutatModel = when (zutat.einheit) {
    "kg" -> zutat.copy(menge = zutat.menge * 1000, einheit = "g")
    "l" -> zutat.copy(menge = zutat.menge * 1000, einheit = "ml")
    else -> zutat
}

// Ab 1000 g / ml wieder schön als kg / l anzeigen und Rundungsreste (0.30000000000000004) entfernen
private fun huebsch(zutat: ZutatModel): ZutatModel {
    val gerundet = round(zutat.menge * 100) / 100
    return when {
        zutat.einheit == "g" && gerundet >= 1000 -> zutat.copy(menge = round(gerundet / 10) / 100, einheit = "kg")
        zutat.einheit == "ml" && gerundet >= 1000 -> zutat.copy(menge = round(gerundet / 10) / 100, einheit = "l")
        else -> zutat.copy(menge = gerundet)
    }
}

private const val ML_PRO_SCHUSS = 20.0

fun ladeEinkaufsliste(database: EssensplanDatabase, plan: List<WochenplanEintrag>): List<ZutatModel> {
    val eindeutigeGerichtIds = plan.map { it.gericht.id }.distinct()
    val rohZutaten = mutableListOf<ZutatModel>()

    for (gerichtId in eindeutigeGerichtIds) {
        val zutatenZeilen = database.gerichtQueries.selectAlleZutatenFuerGericht(gerichtId).executeAsList()
        val zutatenModels = zutatenZeilen.map { zeile ->
            ZutatModel(name = zeile.name, menge = zeile.menge, einheit = zeile.einheit)
        }
        rohZutaten.addAll(zutatenModels)
    }

    // Erst nach Namen gruppieren (ohne Groß-/Kleinschreibung, Aliase wie Magerquark -> Quark)
    val nachName = rohZutaten.groupBy { zutat ->
        val klein = zutat.name.trim().lowercase()
        (zutatenAliase[klein] ?: klein).lowercase()
    }

    return nachName.values.flatMap { gruppe ->
        val ersterName = gruppe.first().name.trim()
        val anzeigeName = zutatenAliase[ersterName.lowercase()] ?: ersterName

        var einheitlich = gruppe
            .map { ZutatModel(anzeigeName, it.menge, normalisiereEinheit(it.einheit)) }
            .map { zuBasiseinheit(it) }

        // Schuss nur dann in ml umrechnen, wenn dieselbe Zutat auch in ml vorkommt
        if (einheitlich.any { it.einheit == "ml" }) {
            einheitlich = einheitlich.map {
                if (it.einheit.equals("Schuss", ignoreCase = true)) {
                    ZutatModel(it.name, it.menge * ML_PRO_SCHUSS, "ml")
                } else it
            }
        }

        einheitlich
            .groupBy { it.einheit }
            .map { (einheit, teil) -> huebsch(ZutatModel(anzeigeName, teil.sumOf { it.menge }, einheit)) }
    }
}

fun formatMenge(menge: Double): String {
    return if (menge % 1.0 == 0.0) {
        menge.toInt().toString()
    } else {
        menge.toString()
    }
}

fun waehleErsatzgericht(plan: List<WochenplanEintrag>, alleGerichte: List<GerichtModel>,
                        eintrag: WochenplanEintrag): GerichtModel? {
    val belegteIds = plan.map { it.gericht.id }
    val kandidaten = alleGerichte.filter {
        it.kategorie == eintrag.kategorie && it.id !in belegteIds
    }

    return kandidaten.randomOrNull()
}