package com.food.essensplan

import app.cash.sqldelight.Query
import app.cash.sqldelight.Transacter
import app.cash.sqldelight.db.QueryResult
import app.cash.sqldelight.db.SqlCursor
import app.cash.sqldelight.db.SqlDriver
import app.cash.sqldelight.db.SqlPreparedStatement
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

// SQLDelight-Treiber für den Browser. Dahinter läuft sql.js (SQLite als WebAssembly, im Hauptthread).
// Der Treiber ist synchron, genau wie auf Android und iOS - deshalb muss App.kt nicht angepasst werden.
// Nach jeder Änderung wird die komplette Datenbank (ein paar KB) kurz verzögert in IndexedDB gesichert.
class SqlJsTreiber(
    private var db: dynamic,
    private val speicher: suspend (dynamic) -> Unit
) : SqlDriver {

    private var transaktion: Transacter.Transaction? = null
    private val listeners = mutableMapOf<String, MutableSet<Query.Listener>>()
    private val scope = CoroutineScope(Dispatchers.Default)
    private var speicherJob: Job? = null
    private var geaendert = false

    // ---- Abfragen ------------------------------------------------------------------------------

    override fun <R> executeQuery(
        identifier: Int?,
        sql: String,
        mapper: (SqlCursor) -> QueryResult<R>,
        parameters: Int,
        binders: (SqlPreparedStatement.() -> Unit)?
    ): QueryResult<R> {
        val stmt = db.prepare(sql)
        try {
            if (parameters > 0 || binders != null) stmt.bind(werteFuer(parameters, binders))
            val zeilen = ArrayList<dynamic>()
            while (stmt.step() as Boolean) zeilen.add(stmt.get())
            return mapper(Cursor(zeilen))
        } finally {
            stmt.free()
        }
    }

    override fun execute(
        identifier: Int?,
        sql: String,
        parameters: Int,
        binders: (SqlPreparedStatement.() -> Unit)?
    ): QueryResult<Long> {
        if (parameters > 0 || binders != null) db.run(sql, werteFuer(parameters, binders)) else db.run(sql)
        val betroffen = (db.getRowsModified() as Number).toLong()
        // Innerhalb einer Transaktion wird erst beim Commit gesichert
        if (transaktion == null) planeSpeichern()
        return QueryResult.Value(betroffen)
    }

    private fun werteFuer(parameters: Int, binders: (SqlPreparedStatement.() -> Unit)?): Array<Any?> {
        val werte = arrayOfNulls<Any>(parameters)
        binders?.invoke(Binder(werte))
        return werte
    }

    private class Binder(private val werte: Array<Any?>) : SqlPreparedStatement {
        override fun bindBytes(index: Int, bytes: ByteArray?) {
            werte[index] = if (bytes == null) null else alsUint8Array(bytes)
        }
        override fun bindLong(index: Int, long: Long?) { werte[index] = long?.toDouble() }
        override fun bindDouble(index: Int, double: Double?) { werte[index] = double }
        override fun bindString(index: Int, string: String?) { werte[index] = string }
        override fun bindBoolean(index: Int, boolean: Boolean?) {
            werte[index] = boolean?.let { if (it) 1.0 else 0.0 }
        }
    }

    private class Cursor(private val zeilen: List<dynamic>) : SqlCursor {
        private var position = -1
        private val zeile: dynamic get() = zeilen[position]

        override fun next(): QueryResult<Boolean> {
            position++
            return QueryResult.Value(position < zeilen.size)
        }
        override fun getString(index: Int): String? {
            val v: dynamic = zeile[index]
            return if (v == null) null else v.toString() as String
        }
        override fun getLong(index: Int): Long? {
            val v: dynamic = zeile[index]
            return if (v == null) null else (v as Number).toLong()
        }
        override fun getDouble(index: Int): Double? {
            val v: dynamic = zeile[index]
            return if (v == null) null else (v as Number).toDouble()
        }
        override fun getBoolean(index: Int): Boolean? = getLong(index)?.let { it != 0L }
        override fun getBytes(index: Int): ByteArray? {
            val v: dynamic = zeile[index]
            return if (v == null) null else alsByteArray(v)
        }
    }

    // ---- Transaktionen -------------------------------------------------------------------------

    private inner class Transaktion(
        override val enclosingTransaction: Transacter.Transaction?
    ) : Transacter.Transaction() {
        override fun endTransaction(successful: Boolean): QueryResult<Unit> {
            if (enclosingTransaction == null) {
                if (successful) {
                    db.run("COMMIT")
                    planeSpeichern()
                } else {
                    db.run("ROLLBACK")
                }
            }
            transaktion = enclosingTransaction
            return QueryResult.Unit
        }
    }

    override fun newTransaction(): QueryResult<Transacter.Transaction> {
        val aeussere = transaktion
        val neue = Transaktion(aeussere)
        if (aeussere == null) db.run("BEGIN TRANSACTION")
        transaktion = neue
        return QueryResult.Value(neue)
    }

    override fun currentTransaction(): Transacter.Transaction? = transaktion

    // ---- Listener (damit Queries sich nach Änderungen aktualisieren) ---------------------------

    override fun addListener(vararg queryKeys: String, listener: Query.Listener) {
        queryKeys.forEach { listeners.getOrPut(it) { linkedSetOf() }.add(listener) }
    }

    override fun removeListener(vararg queryKeys: String, listener: Query.Listener) {
        queryKeys.forEach { listeners[it]?.remove(listener) }
    }

    override fun notifyListeners(vararg queryKeys: String) {
        queryKeys.flatMap { listeners[it].orEmpty() }.distinct().forEach { it.queryResultsChanged() }
    }

    // ---- Sichern in IndexedDB ------------------------------------------------------------------

    private fun planeSpeichern() {
        geaendert = true
        speicherJob?.cancel()
        speicherJob = scope.launch {
            delay(300)
            speichereJetzt()
        }
    }

    // Wird auch aufgerufen, wenn die App in den Hintergrund geht (iOS beendet sie dort gern ohne Vorwarnung)
    fun speichereJetzt() {
        if (!geaendert || transaktion != null) return
        geaendert = false
        val bytes = db.export()
        scope.launch { speicher(bytes) }
    }

    // Tauscht die Datenbank komplett aus (Import). Die alte wird erst danach geschlossen.
    fun ersetzeDatenbank(neu: dynamic) {
        val alt = db
        db = neu
        transaktion = null
        speicherJob?.cancel()
        geaendert = false
        try { alt.close() } catch (e: dynamic) {}
    }

    fun exportBytes(): dynamic = db.export()

    override fun close() {
        speichereJetzt()
        db.close()
    }
}

internal fun alsUint8Array(bytes: ByteArray): dynamic {
    val b: dynamic = bytes
    return js("new Uint8Array(b.buffer, b.byteOffset, b.length)")
}

internal fun alsByteArray(u8: dynamic): ByteArray {
    val v: dynamic = u8
    return js("new Int8Array(v.buffer, v.byteOffset, v.length)").unsafeCast<ByteArray>()
}
