package com.food.essensplan

import androidx.compose.runtime.getValue
import androidx.compose.runtime.key
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.ExperimentalComposeUiApi
import androidx.compose.ui.window.ComposeViewport
import app.cash.sqldelight.db.QueryResult
import app.cash.sqldelight.db.SqlDriver
import com.food.essensplan.db.EssensplanDatabase
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.await
import kotlinx.coroutines.launch
import kotlin.js.Promise

// Zugriff auf die Helfer aus persist.js und auf sql.js (beides wird in index.html geladen)
private fun speicherJs(): dynamic = js("window.essensplanStore")
private fun initSqlJs(): dynamic = js("window.initSqlJs")

private const val SQLITE_KOPF = "SQLite format 3\u0000"

object WebDatenbank {
    private var sql: dynamic = null          // das von sql.js gelieferte Modul (SQL.Database usw.)
    private var treiber: SqlJsTreiber? = null

    // Muss einmal beim Start aufgerufen werden (lädt SQLite und die gespeicherte Datenbank)
    suspend fun oeffnen(): SqlDriver {
        treiber?.let { return it }
        val konfig: dynamic = js("({ locateFile: function (datei) { return datei; } })")
        sql = (initSqlJs()(konfig) as Promise<dynamic>).await()
        val gespeichert: dynamic = (speicherJs().load() as Promise<dynamic>).await()

        val db: dynamic = if (gespeichert != null) neueDatenbank(gespeichert) else neueDatenbank(null)
        val neu = SqlJsTreiber(db, ::sichern)
        bringSchemaAufStand(neu)
        speicherJs().bitteUmDauerhaftenSpeicher()
        // App im Hintergrund: sofort sichern, bevor das Betriebssystem sie beendet
        js("document").addEventListener("visibilitychange", {
            if (js("document.visibilityState") == "hidden") neu.speichereJetzt()
        })
        js("window").addEventListener("pagehide", { neu.speichereJetzt() })
        treiber = neu
        return neu
    }

    private fun neueDatenbank(bytes: dynamic): dynamic {
        val s = sql
        return if (bytes == null) js("new s.Database()") else js("new s.Database(bytes)")
    }

    // Wie bei Android/iOS: user_version steuert Anlegen bzw. Migration
    private fun bringSchemaAufStand(fahrer: SqlJsTreiber) {
        val schema = EssensplanDatabase.Schema
        val aktuell = fahrer.executeQuery(
            null, "PRAGMA user_version",
            { c -> QueryResult.Value(if (c.next().value) c.getLong(0) ?: 0L else 0L) }, 0
        ).value
        if (aktuell == 0L) {
            schema.create(fahrer)
            fahrer.execute(null, "PRAGMA user_version = ${schema.version}", 0)
        } else if (aktuell < schema.version) {
            schema.migrate(fahrer, aktuell, schema.version)
            fahrer.execute(null, "PRAGMA user_version = ${schema.version}", 0)
        }
    }

    private suspend fun sichern(bytes: dynamic) {
        (speicherJs().save(bytes) as Promise<dynamic>).await()
    }

    fun exportiere(fahrer: SqlDriver) {
        val t = fahrer as SqlJsTreiber
        // Direkt im Klick aufrufen (ohne Umweg über eine Coroutine), sonst blockiert Safari den Teilen-Dialog
        speicherJs().exportiere(t.exportBytes(), "essensplan-backup.db")
    }

    // Wählt eine Datei, prüft sie und ersetzt dann die Datenbank. Danach wird onFertig aufgerufen.
    fun waehleUndImportiere(fahrer: SqlDriver, onFertig: () -> Unit) {
        val t = fahrer as SqlJsTreiber
        // Dateiauswahl direkt im Klick öffnen (Safari erlaubt das nur innerhalb der Benutzeraktion)
        val auswahl = speicherJs().waehleDatei() as Promise<dynamic>
        MainScope().launch {
            val bytes: dynamic = auswahl.await() ?: return@launch
            if (!istSqlite(bytes)) {
                speicherJs().meldung("Keine gültige Datenbank")
                return@launch
            }
            try {
                // 1. Erst eine neue Datenbank daraus öffnen und prüfen. Die laufende bleibt unberührt.
                val neu: dynamic = neueDatenbank(bytes)
                neu.exec("SELECT count(*) FROM sqlite_master")
                // 2. Dauerhaft sichern. Klappt das nicht, bleibt alles wie es war.
                val ok = (speicherJs().save(neu.export()) as Promise<dynamic>).await() as Boolean
                if (!ok) {
                    neu.close()
                    speicherJs().meldung("Import fehlgeschlagen: Speicher nicht verfügbar")
                    return@launch
                }
                // 3. Erst jetzt tauschen und das Schema ggf. aktualisieren
                t.ersetzeDatenbank(neu)
                bringSchemaAufStand(t)
                onFertig()
            } catch (e: dynamic) {
                speicherJs().meldung("Import fehlgeschlagen")
            }
        }
    }

    private fun istSqlite(bytes: dynamic): Boolean {
        if ((bytes.length as Int) < 16) return false
        for (i in SQLITE_KOPF.indices) {
            if ((bytes[i] as Int) != SQLITE_KOPF[i].code) return false
        }
        return true
    }
}

// Einstieg der Web-Version (wird von webApp/main.kt aufgerufen)
@OptIn(ExperimentalComposeUiApi::class)
fun starteWebApp() {
    CoroutineScope(Dispatchers.Default).launch {
        val fahrer = WebDatenbank.oeffnen()
        val spinner: dynamic = js("document.getElementById('spinner')")
        if (spinner != null) spinner.remove()
        ComposeViewport {
            // Nach einem Import erhöht, dann wird über key(...) alles mit der neuen Datenbank neu aufgebaut
            var generation by remember { mutableStateOf(0) }
            key(generation) {
                val database = remember(fahrer) { EssensplanDatabase(fahrer) }
                App(
                    database = database,
                    onExport = { WebDatenbank.exportiere(fahrer) },
                    onImport = { WebDatenbank.waehleUndImportiere(fahrer) { generation++ } }
                )
            }
        }
    }
}
