package com.food.essensplan

import androidx.compose.ui.platform.Clipboard
import kotlinx.coroutines.await
import kotlin.js.Promise

actual suspend fun kopiereInZwischenablage(clipboard: Clipboard, text: String) {
    try {
        (js("navigator.clipboard.writeText(text)") as Promise<dynamic>).await()
    } catch (e: Throwable) {
        // Z. B. wenn der Browser den Zugriff verweigert - dann bleibt die Zwischenablage unverändert
    }
}
