package com.food.essensplan.db

import app.cash.sqldelight.Transacter
import app.cash.sqldelight.db.QueryResult
import app.cash.sqldelight.db.SqlDriver
import app.cash.sqldelight.db.SqlSchema
import com.food.essensplan.GerichtQueries
import com.food.essensplan.WochenplanQueries
import com.food.essensplan.db.shared.newInstance
import com.food.essensplan.db.shared.schema
import kotlin.Unit

public interface EssensplanDatabase : Transacter {
  public val gerichtQueries: GerichtQueries

  public val wochenplanQueries: WochenplanQueries

  public companion object {
